#!/usr/bin/env python3
"""Rebuild each concept note's "Discussed in" list (runs locally; costs no tokens).

A concept note is any note with `type: Concept` (normally in Concepts/). An analysis note
(`type: Analysis` or `Part Analysis`) lists the concepts it uses in its `concepts` frontmatter and,
under "## Key concepts", one line per concept: `- [[Concept]] — how this item uses it (cite)`.
This script writes, at the end of every concept note, a generated section:

    ## Discussed in
    <!-- generated by vault-librarian build_concepts.py; ... -->
    - [[<work> (Analysis)|<item title>]] — how that item uses the concept
    <!-- end of generated list -->

When two analyses that both use the concept are linked "disagrees" in either one's Related list, the
generated part also gets a "### Where your sources disagree" list (each pair once).

Only the generated part is rewritten, and only when it changed; The owner's own text above it is kept.
Aliases count: an analysis that lists a concept by one of its aliases is included.

Usage:
  python build_concepts.py <vault> [--dry-run]
"""
import argparse
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from vaultlib import RESERVED, split_frontmatter, walk

MARK = "<!-- generated by vault-librarian build_concepts.py; the list follows each analysis's concepts -->"
END = "<!-- end of generated list -->"
SECTION = re.compile(r"(?s)\n*## Discussed in\s*\n" + re.escape(MARK) + r".*?" + re.escape(END) + r"\n?")
RELLINE = re.compile(r"^- \*\*disagrees\*\* — \[\[([^\]|#]+)(?:\|[^\]]*)?\]\]:?\s*(.*)$")
KEYLINE = re.compile(r"^- \[\[([^\]|#]+)(?:\|[^\]]*)?\]\]\s*[—–-]\s*(.*)$")
ANALYSIS_TYPES = {"Analysis", "Part Analysis"}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("vault")
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()
    vault = os.path.abspath(a.vault)
    concepts, analyses = {}, []
    for rel, ab in walk(vault):
        if not rel.lower().endswith(".md") or rel.rsplit("/", 1)[-1] in RESERVED:
            continue
        with open(ab, encoding="utf-8", errors="replace") as f:
            text = f.read()
        fm, _, body = split_frontmatter(text)
        if not isinstance(fm, dict):
            continue
        name = rel.rsplit("/", 1)[-1][:-3]
        if fm.get("type") == "Concept":
            al = fm.get("aliases") or []
            concepts[name] = {"rel": rel, "ab": ab, "text": text,
                              "keys": {name.lower(), str(fm.get("title") or name).lower()}
                              | {str(x).lower() for x in (al if isinstance(al, list) else [al])}}
        elif fm.get("type") in ANALYSIS_TYPES:
            gloss, dis = {}, []
            for ln in body.splitlines():
                m = KEYLINE.match(ln.strip())
                if m:
                    gloss[m.group(1).strip().lower()] = m.group(2).strip()
                m = RELLINE.match(ln.strip())
                if m:
                    dis.append((m.group(1).strip(), m.group(2).strip()))
            of = re.match(r"\[\[([^\]|#]+)", str(fm.get("analysis_of") or ""))
            analyses.append({"name": name, "title": str(fm.get("title") or name),
                             "uses": [str(c) for c in (fm.get("concepts") or [])], "gloss": gloss,
                             "item": of.group(1).strip() if of else None, "dis": dis})
    wrote = 0
    for cname, c in sorted(concepts.items()):
        rows = []
        for an in sorted(analyses, key=lambda x: x["title"].lower()):
            used = [u for u in an["uses"] if u.lower() in c["keys"]]
            if not used:
                continue
            g = an["gloss"].get(cname.lower()) or an["gloss"].get(used[0].lower()) or ""
            title = re.sub(r"(?: - Analysis| \(Analysis\))$", "", an["title"])   # both naming forms (2026-10-10)
            rows.append(f"- [[{an['name']}|{title}]]" + (f" — {g}" if g else ""))
        users = [an for an in analyses if any(u.lower() in c["keys"] for u in an["uses"])]
        items = {an["item"] for an in users if an["item"]}
        dis, seen = [], set()
        for an in sorted(users, key=lambda x: x["title"].lower()):
            for tgt, why in an["dis"]:
                pair = frozenset((an["item"], tgt))
                if an["item"] and tgt in items and pair not in seen:
                    seen.add(pair)
                    dis.append(f"- [[{an['item']}]] disagrees with [[{tgt}]]" + (f": {why}" if why else ""))
        section = ("\n\n## Discussed in\n" + MARK + "\n" + ("\n".join(rows) if rows else "- (no analyses yet)") + "\n"
                   + ("\n### Where your sources disagree\n\n" + "\n".join(dis) + "\n" if dis else "") + END + "\n")
        old = c["text"]
        base = SECTION.sub("", old).rstrip("\n")
        new = base + section
        if new != old:
            wrote += 1
            if not a.dry_run:
                with open(c["ab"], "w", encoding="utf-8", newline="\n") as f:
                    f.write(new)
            print(f"{'would update' if a.dry_run else 'updated'} {c['rel']} ({len(rows)} analyses)")
    print(f"{len(concepts)} concepts, {len(analyses)} analyses, {wrote} concept notes {'to update' if a.dry_run else 'updated'}")


if __name__ == "__main__":
    main()
